class Solution {
public:
    long long sumOfWeightedModes(vector<int>& nums, int k) {
        int n = nums.size();
        unordered_map<int,int> cnt, fc;
        vector<priority_queue<int, vector<int>, greater<int>>> heaps(200005);
        int maxF = 0; long long ans = 0;
        for (int i = 0; i < n; i++) {
            int f = ++cnt[nums[i]];
            fc[f-1]--; fc[f]++;
            heaps[f].push(nums[i]);
            if (f > maxF) maxF = f;
            if (i >= k) {
                int y = nums[i - k];
                f = --cnt[y];
                fc[f+1]--; fc[f]++;
                if (f + 1 == maxF && fc[maxF] == 0) maxF--;
            }
            if (i >= k - 1) {
                auto& h = heaps[maxF];
                while (cnt[h.top()] != maxF) h.pop();
                ans += (long long)maxF * h.top();
            }
        }
        return ans;
    }
};

