class Solution {
    public long sumOfWeightedModes(int[] nums, int k) {
        int n = nums.length;
        HashMap<Integer,Integer> cnt = new HashMap<>(), fc = new HashMap<>();
        List<PriorityQueue<Integer>> heaps = new ArrayList<>();
        for (int i = 0; i <= n + 1; i++) heaps.add(new PriorityQueue<>());
        int maxF = 0; long ans = 0;
        for (int i = 0; i < n; i++) {
            int f = cnt.merge(nums[i], 1, Integer::sum);
            fc.merge(f - 1, -1, Integer::sum); fc.merge(f, 1, Integer::sum);
            heaps.get(f).offer(nums[i]);
            if (f > maxF) maxF = f;
            if (i >= k) {
                int y = nums[i - k];
                f = cnt.merge(y, -1, Integer::sum);
                fc.merge(f + 1, -1, Integer::sum); fc.merge(f, 1, Integer::sum);
                if (f + 1 == maxF && fc.getOrDefault(maxF, 0) == 0) maxF--;
            }
            if (i >= k - 1) {
                PriorityQueue<Integer> h = heaps.get(maxF);
                while (cnt.get(h.peek()) != maxF) h.poll();
                ans += (long) maxF * h.peek();
            }
        }
        return ans;
    }
}

