var sumOfWeightedModes = function(nums, k) {
    const n = nums.length;
    const cnt = new Map(), fc = new Map();
    const heaps = Array.from({length: n + 2}, () => []);
    const push = (h, x) => { h.push(x); let i = h.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (h[p] <= h[i]) break; [h[p], h[i]] = [h[i], h[p]]; i = p; } };
    const pop = (h) => { const t = h[0], l = h.pop(); if (h.length) { h[0] = l; let i = 0;
        for (;;) { let c = 2*i+1; if (c >= h.length) break; if (c+1 < h.length && h[c+1] < h[c]) c++;
            if (h[i] <= h[c]) break; [h[i], h[c]] = [h[c], h[i]]; i = c; } } return t; };
    let maxF = 0, ans = 0;
    for (let i = 0; i < n; i++) {
        const x = nums[i];
        const f = (cnt.get(x) || 0) + 1; cnt.set(x, f);
        fc.set(f - 1, (fc.get(f - 1) || 0) - 1); fc.set(f, (fc.get(f) || 0) + 1);
        push(heaps[f], x);
        if (f > maxF) maxF = f;
        if (i >= k) {
            const y = nums[i - k];
            const g = cnt.get(y) - 1; cnt.set(y, g);
            fc.set(g + 1, fc.get(g + 1) - 1); fc.set(g, (fc.get(g) || 0) + 1);
            if (g + 1 === maxF && !fc.get(maxF)) maxF--;
        }
        if (i >= k - 1) {
            const h = heaps[maxF];
            while (cnt.get(h[0]) !== maxF) pop(h);
            ans += maxF * h[0];
        }
    }
    return ans;
};

