class Solution:
    def sumOfWeightedModes(self, nums: List[int], k: int) -> int:
        ans = 0
        for i in range(len(nums) - k + 1):
            c = collections.Counter(nums[i:i+k])
            m = max(c.values())
            v = min(x for x in c if c[x] == m)
            ans += m * v
        return ans

