class Solution {
public:
    long long sumOfWeightedModes(vector<int>& nums, int k) {
        long long ans = 0;
        for (int i = 0; i + k <= (int)nums.size(); i++) {
            unordered_map<int,int> c;
            for (int j = i; j < i + k; j++) c[nums[j]]++;
            int m = 0, v = INT_MAX;
            for (auto& [x, f] : c)
                if (f > m || (f == m && x < v)) { m = f; v = x; }
            ans += (long long)m * v;
        }
        return ans;
    }
};

