class Solution {
    public long sumOfWeightedModes(int[] nums, int k) {
        long ans = 0;
        for (int i = 0; i + k <= nums.length; i++) {
            HashMap<Integer,Integer> c = new HashMap<>();
            for (int j = i; j < i + k; j++) c.merge(nums[j], 1, Integer::sum);
            int m = 0, v = Integer.MAX_VALUE;
            for (var e : c.entrySet()) {
                int x = e.getKey(), f = e.getValue();
                if (f > m || (f == m && x < v)) { m = f; v = x; }
            }
            ans += (long) m * v;
        }
        return ans;
    }
}

